      ],
      "badExamples": [
        "Time"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "DatePicker",
      "relationship": "Pair for date+time scheduling",
      "example": "<DatePicker aria-label=\"Date\" /><TimePicker aria-label=\"Time\" />"
    }
  ],
  "relatedComponents": [
